def transform(grid):
    """
    Transform grid based on ARC patterns:
    - Detect background color (most common)
    - Find row/col separations
    - Fill based on matching patterns between segments
    """
    h, w = len(grid), len(grid[0])

    # Find background color (most common)
    bg = collections.Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Find rows that are uniform (potential separation lines)
    uniform_rows = [i for i in range(h) if len(set(grid[i])) == 1 and grid[i][0] == bg]
    # Find columns that are uniform
    uniform_cols = [j for j in range(w) if len(set(grid[i][j] for i in range(h))) == 1 and grid[0][j] == bg]

    # If we found uniform rows or cols, use the task-026adbf3 pattern
    if uniform_rows and uniform_cols:
        sep_r = uniform_rows[0]
        sep_c = uniform_cols[0]

        top_left = [grid[r][:sep_c] for r in range(sep_r)]
        top_right = [grid[r][:] for r in range(sep_r)]

        if top_left and top_left[0]:
            output = []
            for r in range(sep_r):
                row = []
                for c in range(sep_c):
                    if top_left[r][c] == top_right[r][c]:
                        row.append(3)
                    else:
                        row.append(bg)
                output.append(row)
            return output

    # Default pattern: diagonal fill
    out = [row[:] for row in grid]

    for keyf in (lambda r,c:r-c, lambda r,c:r+c):
        lines = {}
        for r in range(h):
            for c in range(w):
                if grid[r][c] != bg:
                    lines.setdefault(keyf(r,c), []).append((r, c))

        for k2, pts in lines.items():
