def can_reach_seed_orthogonal(path, grid):
    """Check if given path avoids 2s"""
    for r, c in path:
        if 0 <= r < len(grid) and 0 <= c < len(grid[0]):
            if grid[r][c] == 2:
                return False
    return True

def check_L_path_to_seed(r, c, grid):
    """
    Check if (r,c) can reach seed by L-path: vertical then horizontal, OR horizontal then vertical
    Looking at 2x2 seed at (6,8),(6,9),(7,8),(7,9):
    L-path: 
    - Go vertical to row 6 or 7, then horizontal to col 8 or 9
    - Must avoid 2s on the path
    """
    # Try all 4 L-shaped paths to seed
    for sr in [6, 7]:
        for sc in [8, 9]:
            # L-path: (r,c) -> (sr,c) -> (sr,sc)  vertical then horizontal
            path = [(r,c)]
            # vertical segment (r,c) to (sr,c)
            if sr > r:
                for rr in range(r+1, sr+1):
                    path.append((rr, c))
            elif sr < r:
                for rr in range(r-1, sr-1, -1):
                    path.append((rr, c))
            # horizontal segment (sr,c) to (sr,sc)
            if sc > c:
                for cc in range(c+1, sc+1):
                    path.append((sr, cc))
            elif sc < c:
                for cc in range(c-1, sc-1, -1):
                    path.append((sr, cc))

            if can_reach_seed_orthogonal(path, grid):
                return True

            # Also try horizontal then vertical: (r,c) -> (r,sc) -> (sr,sc)
            path = [(r,c)]
            if sc > c:
                for cc in range(c+1, sc+1):
                    path.append((r, cc))
            elif sc < c:
                for cc in range(c-1, sc-1, -1):
                    path.append((r, cc))
            if sr > r:
                for rr in range(r+1, sr+1):
                    path.append((rr, sc))
            elif sr < r:
                for rr in range(r-1, sr-1, -1):
                    path.append((rr, sc))

            if can_reach_seed_orthogonal(path, grid):
                return True
    return False

